static AE_NEXT_ID:AtomicU64=AtomicU64::new(1);
fn ae_id()->u64{AE_NEXT_ID.fetch_update(AeOrdering::SeqCst,AeOrdering::SeqCst,|n|n.checked_add(1)).expect("identity_limit")}
