fn ae_check(t:&J,v:&Value,seen:&mut HashSet<String>,depth:usize){if depth>64{panic!("type_depth")}match t["t"].as_str().unwrap(){
 "Fn"|"Task"=>ae_executable_check(t,v),
 "Nominal"=>ae_check(&t["repr"],v,seen,depth+1),"Owned"=>ae_check(&t["inner"],v,seen,depth+1),
 "Record"=>{let r=if let Value::Record(r)=v{r}else{panic!("record_type")};let (id,ty,fields)={let row=r.borrow();if !row.live{panic!("record_retired")}(row.id,row.ty.clone(),row.fields.clone())};if ae_type_base(&ty)["name"]!=t["name"]{panic!("record_type")}if !seen.insert(format!("{}:{}",id,t)){return}let expected=t["fields"].as_array().unwrap();if fields.len()!=expected.len(){panic!("record_fields")}for f in expected{let name=f[0].as_str().unwrap();let value=&fields.iter().find(|(key,_)|key==name).expect("record_fields").1;ae_check(&f[1],value,seen,depth+1);}},
 "Seq"=>{for item in ae_items(v.clone()){ae_check(&t["element"],&item,seen,depth+1);}},
 "Result"=>{let r=if let Value::Result(r)=v{r}else{panic!("result_type")};let (variant,value)={let row=r.borrow();(row.variant.clone(),row.value.clone())};ae_check(&t[&variant],&value,seen,depth+1);},
 _=>{ae_scalar_bind(&t.to_string(),v.clone());}
}}
pub fn ae_bind(text:&str,v:Value)->Value{ae_check(&serde_json::from_str::<J>(text).unwrap(),&v,&mut HashSet::new(),0);v}
fn ae_regions(v:&Value,out:&mut HashSet<u64>,seen:&mut HashSet<u64>){if let Some((_,id))=ae_identity(v){if !seen.insert(id){return}match v{Value::Record(r)=>{out.insert(id);for(_,x)in r.borrow().fields.clone(){ae_regions(&x,out,seen);}},Value::Seq(r)=>{for x in r.borrow().items.clone(){ae_regions(&x,out,seen);}},Value::Result(r)=>ae_regions(&r.borrow().value.clone(),out,seen),Value::Closure(c)=>{for x in &c.captures{ae_regions(x,out,seen);}},Value::Task(t)=>{let(captures,result)={let row=t.borrow();(row.captures.clone(),row.result.clone())};for x in captures{ae_regions(&x,out,seen);}ae_regions(&result,out,seen);},_=>{}}}}
pub fn ae_arguments(text:&str,args:&[Value]){let types:J=serde_json::from_str(text).unwrap();let types=types.as_array().unwrap();ae_arity(args,types.len());let mut owned:Vec<HashSet<u64>>=vec![];let mut borrowed=HashSet::new();
 fn visit(t:&J,v:&Value,region:Option<usize>,owned:&mut Vec<HashSet<u64>>,borrowed:&mut HashSet<u64>,seen:&mut HashSet<String>){match t["t"].as_str().unwrap(){"Fn"|"Task"=>{if let Some(i)=region{ae_regions(v,&mut owned[i],&mut HashSet::new());}else{ae_regions(v,borrowed,&mut HashSet::new());}},"Nominal"=>visit(&t["repr"],v,region,owned,borrowed,seen),"Owned"=>{let index=region.unwrap_or_else(||{owned.push(HashSet::new());owned.len()-1});ae_regions(v,&mut owned[index],&mut HashSet::new());visit(&t["inner"],v,Some(index),owned,borrowed,seen)},"Record"=>{let r=if let Value::Record(r)=v{r}else{panic!("record_type")};let(id,fields)={let row=r.borrow();(row.id,row.fields.clone())};if !seen.insert(format!("{}:{}:{:?}",id,t,region)){return}if let Some(i)=region{owned[i].insert(id);}else{borrowed.insert(id);}for f in t["fields"].as_array().unwrap(){let x=&fields.iter().find(|(name,_)|name==f[0].as_str().unwrap()).unwrap().1;visit(&f[1],x,region,owned,borrowed,seen);}},"Seq"=>{for x in ae_items(v.clone()){visit(&t["element"],&x,region,owned,borrowed,seen);}},"Result"=>{let r=if let Value::Result(r)=v{r}else{panic!("result_type")};let(variant,x)={let row=r.borrow();(row.variant.clone(),row.value.clone())};visit(&t[&variant],&x,region,owned,borrowed,seen)},_=>{}}}
 for(t,v)in types.iter().zip(args){ae_check(t,v,&mut HashSet::new(),0);visit(t,v,None,&mut owned,&mut borrowed,&mut HashSet::new());}let mut all=HashSet::new();for region in owned{for id in region{if borrowed.contains(&id)||!all.insert(id){panic!("owned_overlap")}}}}
pub fn ae_snapshot(v:Value)->Value{fn copy(v:Value,memo:&mut HashMap<u64,Value>)->Value{if matches!(v,Value::Closure(_)|Value::Task(_)){return v}let id=match ae_identity(&v){Some((_,id))=>id,None=>return v};if let Some(value)=memo.get(&id){return value.clone()}match v{Value::Record(r)=>{let(ty,fields)={let row=r.borrow();if !row.live{panic!("record_retired")}(row.ty.clone(),row.fields.clone())};let copy=Rc::new(RefCell::new(AeRecord{ty,fields:vec![],id,frozen:true,live:true}));let value=Value::Record(copy.clone());memo.insert(id,value.clone());copy.borrow_mut().fields=fields.into_iter().map(|(k,v)|(k,copy_value(v,memo))).collect();value},Value::Seq(r)=>{let items=r.borrow().items.clone();let copy=Rc::new(RefCell::new(AeSeq{items:vec![],id}));let value=Value::Seq(copy.clone());memo.insert(id,value.clone());copy.borrow_mut().items=items.into_iter().map(|v|copy_value(v,memo)).collect();value},Value::Result(r)=>{let(variant,item)={let row=r.borrow();(row.variant.clone(),row.value.clone())};let copy=Rc::new(RefCell::new(AeResult{variant,value:Value::Unit,id}));let value=Value::Result(copy.clone());memo.insert(id,value.clone());copy.borrow_mut().value=copy_value(item,memo);value},_=>unreachable!()}}fn copy_value(v:Value,memo:&mut HashMap<u64,Value>)->Value{copy(v,memo)}copy(v,&mut HashMap::new())}
pub fn ae_record(text:&str,fields:Vec<(&str,Value)>)->Value{let ty:J=serde_json::from_str(text).unwrap();let base=ae_type_base(&ty);let expected=base["fields"].as_array().expect("record_type");let names:HashSet<&str>=fields.iter().map(|(k,_)|*k).collect();if base["t"]!="Record"||names.len()!=fields.len()||expected.len()!=fields.len(){panic!("record_fields")}for f in expected{let value=&fields.iter().find(|(name,_)|*name==f[0].as_str().unwrap()).expect("record_fields").1;ae_check(&f[1],value,&mut HashSet::new(),0);}ae_allocate_record(ty,fields.into_iter().map(|(k,v)|(k.to_string(),v)).collect())}
pub fn ae_field(v:Value,name:&str)->Value{if let Value::Record(r)=v{if !r.borrow().live{panic!("record_retired")}let out=r.borrow().fields.iter().find(|(k,_)|k==name).expect("record_field").1.clone();out}else{panic!("record_field")}}
pub fn ae_set_field(value:Value,v:Value,name:&str){let r=if let Value::Record(r)=v{r}else{panic!("record_write")};let ty={let row=r.borrow();if !row.live||row.frozen{panic!("record_write")}let base=ae_type_base(&row.ty);base["fields"].as_array().unwrap().iter().find(|f|f[0].as_str()==Some(name)).expect("record_field")[1].clone()};ae_check(&ty,&value,&mut HashSet::new(),0);ae_record_write(&r,name);r.borrow_mut().fields.iter_mut().find(|(k,_)|k==name).expect("record_field").1=value;}
pub fn ae_read_place(mut root:Value,path:&[&str])->Value{for field in path{root=ae_field(root,field);}root}
macro_rules! ae_read_place {($root:expr,[$($field:expr),*])=>{ae_read_place($root,&[$($field),*])}}
pub fn ae_set_place(value:Value,mut root:Value,path:&[&str]){if path.is_empty(){panic!("place_path")}for field in &path[..path.len()-1]{root=ae_field(root,field);}ae_set_field(value,root,path[path.len()-1]);}
macro_rules! ae_set_place {($value:expr,$root:expr,[$($field:expr),*])=>{{let value=$value;let root=$root;ae_set_place(value,root,&[$($field),*]);}}}
pub fn ae_seq(text:&str,items:Vec<Value>)->Value{let ty:J=serde_json::from_str(text).unwrap();if ty["t"]!="Seq"{panic!("sequence_type")}for x in &items{ae_check(&ty["element"],x,&mut HashSet::new(),0);}ae_sequence(items)}
fn ae_sequence(items:Vec<Value>)->Value{Value::Seq(Rc::new(RefCell::new(AeSeq{items,id:ae_id()})))}
pub fn ae_items(v:Value)->Vec<Value>{if let Value::Seq(r)=v{r.borrow().items.clone()}else{panic!("sequence_type")}}
pub fn ae_index(v:Value,index:Value)->Value{use num_traits::ToPrimitive;let items=ae_items(v);let i=ae_num(index);if i<BigInt::zero()||i>=BigInt::from(items.len()){panic!("sequence_bounds")}items[i.to_usize().unwrap()].clone()}
pub fn ae_length(v:Value)->Value{Value::Int(BigInt::from(ae_items(v).len()))}
pub fn ae_result_value(text:&str,variant:&str,value:Value)->Value{let ty:J=serde_json::from_str(text).unwrap();if ty["t"]!="Result"||!(variant=="ok"||variant=="err"){panic!("result_type")}ae_check(&ty[variant],&value,&mut HashSet::new(),0);Value::Result(Rc::new(RefCell::new(AeResult{variant:variant.to_string(),value,id:ae_id()})))}
macro_rules! ae_record {($ty:expr,[$([$key:expr,$value:expr]),*])=>{{let fields=vec![$(($key,$value)),*];ae_record($ty,fields)}}}
macro_rules! ae_seq {($ty:expr,[$($value:expr),*])=>{ae_seq($ty,vec![$($value),*])}}
macro_rules! ae_map {($ctx:expr,$seq:expr,$f:ident)=>{{let items=ae_items($seq);let mut out=vec![];for x in items{$ctx.tick();out.push($f($ctx,vec![x]));}ae_sequence(out)}}}
macro_rules! ae_fold {($ctx:expr,$seq:expr,$initial:expr,$f:ident)=>{{let items=ae_items($seq);let mut out=$initial;for x in items{$ctx.tick();out=$f($ctx,vec![out,x]);}out}}}
macro_rules! ae_match {($value:expr,$ok:ident,$ok_body:expr,$err:ident,$err_body:expr)=>{{let result=$value;let (variant,value)=if let Value::Result(r)=result{let row=r.borrow();(row.variant.clone(),row.value.clone())}else{panic!("result_type")};if variant=="ok"{let $ok=value;$ok_body}else{let $err=value;$err_body}}}}
pub fn ae_json(v:&Value)->String{fn encode(v:&Value,seen:&mut HashSet<u64>)->J{match v{Value::Closure(c)=>return serde_json::json!({"tag":"closure","id":c.id.to_string(),"capabilities":c.meta["capabilities"]}),Value::Task(t)=>return serde_json::json!({"tag":"task","id":t.borrow().id.to_string(),"state":(["pending","running","completed"][t.borrow().state as usize])}),_=>{}}if let Some((_,id))=ae_identity(v){if !seen.insert(id){return serde_json::json!({"tag":"ref","id":id.to_string()})}return match v{Value::Record(r)=>serde_json::json!({"tag":"record","id":id.to_string(),"fields":r.borrow().fields.iter().map(|(k,x)|serde_json::json!([k,encode(x,seen)])).collect::<Vec<_>>()}),Value::Seq(r)=>serde_json::json!({"tag":"sequence","id":id.to_string(),"items":r.borrow().items.iter().map(|x|encode(x,seen)).collect::<Vec<_>>()}),Value::Result(r)=>serde_json::json!({"tag":"result","id":id.to_string(),"variant":r.borrow().variant,"value":encode(&r.borrow().value,seen)}),_=>unreachable!()};}match v{Value::Unit=>serde_json::json!({"tag":"null"}),Value::Int(n)=>serde_json::json!({"tag":"int","value":n.to_string()}),Value::Bool(b)=>serde_json::json!({"tag":"bool","value":b}),Value::Str(s)=>serde_json::json!({"tag":"string","value":s}),_=>unreachable!()}}encode(v,&mut HashSet::new()).to_string()}

#[derive(Debug)]pub struct AeClosure{pub id:u64,pub meta:J,pub captures:Vec<Value>,pub body:fn(&mut Context,&[Value],&[Value])->Value}
#[derive(Debug)]pub struct AeTask{pub id:u64,pub ty:J,pub caps:Vec<String>,pub captures:Vec<Value>,pub body:fn(&mut Context,&[Value],&[Value])->Value,pub state:u8,pub result:Value}
fn ae_type_equal(a:&J,b:&J)->bool{fn norm(v:&J,key:&str)->J{match v{J::Array(xs)=>{let mut values:Vec<J>=xs.iter().map(|x|norm(x,"")).collect();if key=="capabilities"{values.sort_by_key(|v|v.as_str().unwrap().to_string());}J::Array(values)},J::Object(xs)=>J::Object(xs.iter().map(|(k,v)|(k.clone(),norm(v,k))).collect()),_=>v.clone()}}norm(a,"")==norm(b,"")}
fn ae_executable_check(t:&J,v:&Value){if t["t"]=="Fn"{let c=if let Value::Closure(c)=v{c}else{panic!("closure_type")};let actual=serde_json::json!({"t":"Fn","params":c.meta["params"].as_array().unwrap().iter().map(|p|p["ty"].clone()).collect::<Vec<_>>(),"returns":c.meta["returns"],"capabilities":c.meta["capabilities"]});if !ae_type_equal(t,&actual){panic!("closure_type")}}else{let task=if let Value::Task(t)=v{t}else{panic!("task_type")};if !ae_type_equal(t,&task.borrow().ty){panic!("task_type")}}}
fn ae_host_allowed(ctx:&Context,cap:&str)->bool{(ctx.policy)(cap)&&ctx.grants.iter().any(|c|c==cap)}
fn ae_authority(ctx:&Context,caps:&[String]){if caps.iter().any(|c|!ae_host_allowed(ctx,c)||!ctx.frames.last().is_some_and(|f|f.contains(c))){panic!("capability_denied")}}
pub fn ae_capture(values:&[Value],index:&str)->Value{let i:usize=index.parse().expect("capture_index");if i.to_string()!=index{panic!("capture_index")}values.get(i).expect("capture_index").clone()}
pub fn ae_arg(values:&[Value],index:&str)->Value{ae_capture(values,index)}
pub fn ae_lambda(ctx:&mut Context,text:&str,symbols:&[&str],captures:Vec<Value>,body:fn(&mut Context,&[Value],&[Value])->Value)->Value{let meta:J=serde_json::from_str(text).unwrap();let caps:Vec<String>=meta["capabilities"].as_array().unwrap().iter().map(|c|c.as_str().unwrap().to_string()).collect();if symbols.len()!=captures.len(){panic!("capture_shape")}ae_authority(ctx,&caps);Value::Closure(Rc::new(AeClosure{id:ae_id(),meta,captures,body}))}
