export const ae_sub=(a:V,b:V):V=>ae_num(a)-ae_num(b);
export const ae_mul=(a:V,b:V):V=>ae_num(a)*ae_num(b);
export const ae_div=(a:V,b:V):V=>{if(ae_num(b)===0n)throw Error('division_by_zero');return ae_num(a)/ae_num(b);};
export const ae_mod=(a:V,b:V):V=>{if(ae_num(b)===0n)throw Error('division_by_zero');return ae_num(a)%ae_num(b);};
export const ae_lt=(a:V,b:V):V=>ae_num(a)<ae_num(b);
export const ae_le=(a:V,b:V):V=>ae_num(a)<=ae_num(b);
export const ae_gt=(a:V,b:V):V=>ae_num(a)>ae_num(b);
export const ae_ge=(a:V,b:V):V=>ae_num(a)>=ae_num(b);
export const ae_eq=(a:V,b:V):V=>ae_equal(a,b);
export const ae_ne=(a:V,b:V):V=>!ae_equal(a,b);
export const ae_neg=(v:V):V=>-ae_num(v);
export const ae_not=(v:V):V=>!ae_truth(v);
export const ae_concat=(a:V,b:V):V=>{if(typeof a!=='string'||typeof b!=='string')throw Error('type_error');return a+b;};
export const ae_and=(a:()=>V,b:()=>V):V=>ae_truth(a())?b():false;
export const ae_or=(a:()=>V,b:()=>V):V=>ae_truth(a())?true:b();
export const ae_cond=(a:()=>V,b:()=>V,c:()=>V):V=>ae_truth(a())?b():c();
export const ae_call=(ctx:Context,fn:(ctx:Context,args:V[])=>V,args:V[]):V=>fn(ctx,args);
export const ae_invoke=(ctx:Context,cap:string,args:V[]):V=>ctx.invoke(cap,args);
export function ae_forall(ctx:Context,start:V,end:V,body:(value:V)=>V):V{for(let i=ae_num(start);i<ae_num(end);i++){ctx.tick();if(!ae_truth(body(i)))return false;}return true;}
export function ae_fixed(op:string,text:string,a:V,b?:V):V{const t=JSON.parse(text),n=ae_num(op==='cast'?a:({add:ae_add,sub:ae_sub,mul:ae_mul,div:ae_div,mod:ae_mod} as any)[op](a,b));const w=1n<<BigInt(t.bits),min=t.signed?-(w/2n):0n,max=t.signed?w/2n-1n:w-1n;if(n>=min&&n<=max)return n;if(t.overflow==='trap')throw Error('overflow');if(t.overflow==='saturate')return n<min?min:max;return ((n-min)%w+w)%w+min;}

let ae_next_id=1;
const ae_id=()=>{if(!Number.isSafeInteger(ae_next_id+1))throw Error('identity_limit');return ae_next_id++;};
export class AeRecord {readonly kind='record';live=true;ty:any;fields:Map<string,V>;id:number;frozen:boolean;constructor(ty:any,fields:Map<string,V>,id=ae_id(),frozen=false){this.ty=ty;this.fields=fields;this.id=id;this.frozen=frozen;}}
export class AeSeq {readonly kind='sequence';items:V[];id:number;constructor(items:V[],id=ae_id()){this.items=items;this.id=id;}}
export class AeResult {readonly kind='result';variant:'ok'|'err';value:V;id:number;constructor(variant:'ok'|'err',value:V,id=ae_id()){this.variant=variant;this.value=value;this.id=id;}}
function ae_base(t:any):any{return t.t==='Nominal'?ae_base(t.repr):t.t==='Owned'?ae_base(t.inner):t;}
function ae_check(t:any,v:V,seen=new Set<string>(),depth=0):void{
 if(depth>64)throw Error('type_depth');if(t.t==='Fn'||t.t==='Task')return ae_executable_check(t,v);if(t.t==='Nominal')return ae_check(t.repr,v,seen,depth+1);if(t.t==='Owned')return ae_check(t.inner,v,seen,depth+1);
 if(t.t==='Record'){if(!(v instanceof AeRecord)||!v.live||ae_base(v.ty).name!==t.name)throw Error('record_type');const key=v.id+':'+JSON.stringify(t);if(seen.has(key))return;seen.add(key);if(v.fields.size!==t.fields.length)throw Error('record_fields');for(const [name,ty]of t.fields){if(!v.fields.has(name))throw Error('record_fields');ae_check(ty,v.fields.get(name)!,seen,depth+1);}return;}
 if(t.t==='Seq'){if(!(v instanceof AeSeq))throw Error('sequence_type');for(const item of v.items)ae_check(t.element,item,seen,depth+1);return;}
 if(t.t==='Result'){if(!(v instanceof AeResult))throw Error('result_type');return ae_check(v.variant==='ok'?t.ok:t.err,v.value,seen,depth+1);}
 ae_scalar_bind(JSON.stringify(t),v);
}
export function ae_bind(text:string,v:V):V{ae_check(JSON.parse(text),v);return v;}
function ae_regions(v:V,out:Set<number>,seen=new Set<number>()):void{if(v instanceof AeClosure||v instanceof AeTask){if(seen.has(v.id))return;seen.add(v.id);v.captures.forEach(x=>ae_regions(x,out,seen));if(v instanceof AeTask&&v.state==='completed')ae_regions(v.result,out,seen);return;}if(!(v instanceof AeRecord||v instanceof AeSeq||v instanceof AeResult)||seen.has(v.id))return;seen.add(v.id);if(v instanceof AeRecord){out.add(v.id);v.fields.forEach(x=>ae_regions(x,out,seen));}else if(v instanceof AeSeq)v.items.forEach(x=>ae_regions(x,out,seen));else ae_regions(v.value,out,seen);}
export function ae_arguments(text:string,args:V[]):void{const types=JSON.parse(text),owned:Set<number>[]=[],borrowed=new Set<number>();ae_arity(args,types.length);const visit=(t:any,v:V,region:Set<number>|null,seen=new Set<string>()):void=>{if(t.t==='Nominal')return visit(t.repr,v,region,seen);if(t.t==='Owned'){if(region===null){region=new Set();owned.push(region);}ae_regions(v,region);return visit(t.inner,v,region,seen);}if(t.t==='Fn'||t.t==='Task'){ae_regions(v,region??borrowed);return;}if(v instanceof AeRecord&&t.t==='Record'){const key=v.id+':'+JSON.stringify(t)+':'+owned.indexOf(region!);if(seen.has(key))return;seen.add(key);(region??borrowed).add(v.id);for(const[name,ty]of t.fields)visit(ty,v.fields.get(name)!,region,seen);}else if(v instanceof AeSeq&&t.t==='Seq')v.items.forEach(x=>visit(t.element,x,region,seen));else if(v instanceof AeResult&&t.t==='Result')visit(v.variant==='ok'?t.ok:t.err,v.value,region,seen);};types.forEach((t:any,i:number)=>{ae_check(t,args[i]);visit(t,args[i],null);});const ids=new Set<number>();for(const region of owned)for(const id of region){if(ids.has(id)||borrowed.has(id))throw Error('owned_overlap');ids.add(id);}}
export function ae_snapshot(v:V,memo=new Map<number,V>()):V{if(!(v instanceof AeRecord||v instanceof AeSeq||v instanceof AeResult))return v;const prior=memo.get(v.id);if(prior)return prior;if(v instanceof AeRecord){if(!v.live)throw Error('record_retired');const copy=new AeRecord(v.ty,new Map(),v.id,true);memo.set(v.id,copy);v.fields.forEach((x,k)=>copy.fields.set(k,ae_snapshot(x,memo)));return copy;}if(v instanceof AeSeq){const copy=new AeSeq([],v.id);memo.set(v.id,copy);copy.items=v.items.map(x=>ae_snapshot(x,memo));return copy;}const copy=new AeResult(v.variant,null,v.id);memo.set(v.id,copy);copy.value=ae_snapshot(v.value,memo);return copy;}
export function ae_record(text:string,fields:[string,V][]):V{const ty=JSON.parse(text),base=ae_base(ty);if(base.t!=='Record'||new Set(fields.map(x=>x[0])).size!==fields.length||fields.length!==base.fields.length)throw Error('record_fields');for(const[name,t]of base.fields){const value=fields.find(x=>x[0]===name);if(!value)throw Error('record_fields');ae_check(t,value[1]);}return ae_allocate_record(ty,new Map(fields));}
export function ae_field(v:V,name:string):V{if(!(v instanceof AeRecord)||!v.live||!v.fields.has(name))throw Error('record_field');return v.fields.get(name)!;}
export function ae_set_field(value:V,v:V,name:string):void{if(!(v instanceof AeRecord)||!v.live||v.frozen)throw Error('record_write');const field=ae_base(v.ty).fields.find((f:any)=>f[0]===name);if(!field)throw Error('record_field');ae_check(field[1],value);ae_record_write(v,name);v.fields.set(name,value);}
export function ae_seq(text:string,items:V[]):V{const ty=JSON.parse(text);if(ty.t!=='Seq')throw Error('sequence_type');items.forEach(v=>ae_check(ty.element,v));return new AeSeq(items);}
export function ae_items(v:V):V[]{if(!(v instanceof AeSeq))throw Error('sequence_type');return v.items;}
export function ae_index(v:V,index:V):V{const items=ae_items(v),i=ae_num(index);if(i<0n||i>=BigInt(items.length))throw Error('sequence_bounds');return items[Number(i)];}
export const ae_length=(v:V):V=>BigInt(ae_items(v).length);
export function ae_map(ctx:Context,v:V,f:(ctx:Context,args:V[])=>V):V{return new AeSeq([...ae_items(v)].map(item=>{ctx.tick();return f(ctx,[item]);}));}
export function ae_fold(ctx:Context,v:V,initial:V,f:(ctx:Context,args:V[])=>V):V{let result=initial;for(const item of [...ae_items(v)]){ctx.tick();result=f(ctx,[result,item]);}return result;}
export function ae_result_value(text:string,variant:string,value:V):V{const ty=JSON.parse(text);if(ty.t!=='Result'||!['ok','err'].includes(variant))throw Error('result_type');ae_check(ty[variant],value);return new AeResult(variant as 'ok'|'err',value);}
export function ae_match(v:V,ok:(v:V)=>V,err:(v:V)=>V):V{if(!(v instanceof AeResult))throw Error('result_type');return v.variant==='ok'?ok(v.value):err(v.value);}
export function ae_read_place(root:V,path:string[]):V{for(const field of path)root=ae_field(root,field);return root;}
export function ae_set_place(value:V,root:V,path:string[]):void{if(!path.length)throw Error('place_path');let object=root;for(const field of path.slice(0,-1))object=ae_field(object,field);ae_set_field(value,object,path.at(-1)!);}
function ae_equal(a:V,b:V):boolean{if(a instanceof AeClosure||a instanceof AeTask)return(a instanceof AeClosure&&b instanceof AeClosure||a instanceof AeTask&&b instanceof AeTask)&&a.id===(b as AeClosure|AeTask).id;if(a instanceof AeRecord||a instanceof AeSeq||a instanceof AeResult)return (b instanceof AeRecord||b instanceof AeSeq||b instanceof AeResult)&&a.kind===b.kind&&a.id===b.id;return a===b;}
export function ae_json(v:V):string{const seen=new Set<number>();const encode=(v:V):any=>{if(v instanceof AeClosure)return{tag:'closure',id:String(v.id),capabilities:v.meta.capabilities};if(v instanceof AeTask)return{tag:'task',id:String(v.id),state:v.state};if(v instanceof AeRecord||v instanceof AeSeq||v instanceof AeResult){if(seen.has(v.id))return{tag:'ref',id:String(v.id)};seen.add(v.id);if(v instanceof AeRecord)return{tag:'record',id:String(v.id),fields:[...v.fields].map(([k,x])=>[k,encode(x)])};if(v instanceof AeSeq)return{tag:'sequence',id:String(v.id),items:v.items.map(encode)};return{tag:'result',id:String(v.id),variant:v.variant,value:encode(v.value)};}return v===null?{tag:'null'}:typeof v==='bigint'?{tag:'int',value:String(v)}:typeof v==='boolean'?{tag:'bool',value:v}:{tag:'string',value:v};};return JSON.stringify(encode(v));}

export class AeClosure {readonly kind='closure';id=ae_id();constructor(meta:any,captures:V[],body:(ctx:Context,captures:V[],args:V[])=>V){this.meta=meta;this.captures=[...captures];this.body=body;}meta:any;captures:V[];body:(ctx:Context,captures:V[],args:V[])=>V;}
export class AeTask {readonly kind='task';id=ae_id();state:'pending'|'running'|'completed'='pending';result:V=null;constructor(ty:any,caps:string[],captures:V[],body:(ctx:Context,captures:V[],args:V[])=>V){this.ty=ty;this.caps=[...caps];this.captures=[...captures];this.body=body;}ty:any;caps:string[];captures:V[];body:(ctx:Context,captures:V[],args:V[])=>V;}
function ae_type_equal(a:any,b:any):boolean{const normalize=(v:any,key=''):any=>Array.isArray(v)?(key==='capabilities'?[...v].sort():v.map(x=>normalize(x))):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,normalize(v[k],k)])):v;return JSON.stringify(normalize(a))===JSON.stringify(normalize(b));}
function ae_executable_check(t:any,v:V):void{if(t.t==='Fn'){if(!(v instanceof AeClosure)||!ae_type_equal(t,{t:'Fn',params:v.meta.params.map((p:any)=>p.ty),returns:v.meta.returns,capabilities:v.meta.capabilities}))throw Error('closure_type');}else if(!(v instanceof AeTask)||!ae_type_equal(t,v.ty))throw Error('task_type');}
function ae_host_allowed(ctx:Context,cap:string):boolean{const allowed=ctx.policy(cap);return allowed===true&&ctx.grants.includes(cap);}
function ae_authority(ctx:Context,caps:string[]):void{ctx.authority();if(caps.some(c=>!ae_host_allowed(ctx,c)||!ctx.frames.at(-1)?.includes(c)))throw Error('capability_denied');}
export function ae_capture(values:V[],index:string):V{if(!/^(0|[1-9][0-9]*)$/.test(index)||!Number.isSafeInteger(Number(index))||Number(index)>=values.length)throw Error('capture_index');return values[Number(index)];}
export const ae_arg=ae_capture;
export function ae_lambda(ctx:Context,text:string,symbols:string[],captures:V[],body:(ctx:Context,captures:V[],args:V[])=>V):V{const meta=JSON.parse(text);if(symbols.length!==captures.length)throw Error('capture_shape');ae_authority(ctx,meta.capabilities);return new AeClosure(meta,captures,body);}
export function ae_apply(ctx:Context,value:V,args:V[]):V{if(!(value instanceof AeClosure))throw Error('closure_type');ae_authority(ctx,value.meta.capabilities);ae_arguments(JSON.stringify(value.meta.params.map((p:any)=>p.ty)),args);const result=ctx.function(value.meta.capabilities,ctx=>ae_bind(JSON.stringify(value.meta.returns),value.body(ctx,[...value.captures],[...args])));ae_authority(ctx,value.meta.capabilities);return result;}
export function ae_spawn(ctx:Context,text:string,symbols:string[],captures:V[],body:(ctx:Context,captures:V[],args:V[])=>V):V{const ty=JSON.parse(text),caps=ctx.frames.at(-1);if(!caps||ty.t!=='Task'||symbols.length!==captures.length)throw Error('task_shape');ae_authority(ctx,caps);return new AeTask(ty,caps,captures,body);}
export function ae_await(ctx:Context,value:V):V{if(!(value instanceof AeTask))throw Error('task_type');ae_authority(ctx,value.caps);if(value.state==='completed')return value.result;if(value.state==='running')throw Error('task_cycle');value.state='running';try{const result=ctx.function(value.caps,ctx=>ae_bind(JSON.stringify(value.ty.result),value.body(ctx,[...value.captures],[])));value.result=result;value.state='completed';}catch(error){value.state='pending';value.result=null;throw error;}ae_authority(ctx,value.caps);return value.result;}
function ae_effect_values(values:V[]):void{const seen=new Set<object>();const check=(v:V):void=>{if(v instanceof AeClosure||v instanceof AeTask)throw Error('opaque_effect_value');if(v instanceof AeRecord||v instanceof AeSeq||v instanceof AeResult){if(seen.has(v))return;seen.add(v);if(v instanceof AeRecord)v.fields.forEach(check);else if(v instanceof AeSeq)v.items.forEach(check);else check(v.value);}};values.forEach(check);}

const ae_transactions:AeAtomic[]=[];
const ae_recycled_records:AeRecord[]=[];
function ae_undo(operation:()=>void):void{ae_transactions.at(-1)?.undo.push(operation);}
export class AeAtomic {
